            f1_lo = f1_lo | ({32{sel1_c0[k]}} & tv[32*k +: 32]);
            f1_hi = f1_hi | ({32{sel1_c1[k]}} & tv[32*k +: 32]);
            nx_lo = nx_lo | ({32{pc0[k]}} & tv[32*k +: 32]);
            nx_hi = nx_hi | ({32{pc1[k]}} & tv[32*k +: 32]);
        end
    end
    wire [31:0] f1  = {f1_hi[31:16], f1_lo[15:0]};               // = tbl[seg1]
    wire [31:0] nxt = {nx_hi[31:16], nx_lo[15:0]};               // = tbl[ptr[AW-1:0]]
    // Prefetch both first entries while the compiler image is stable (as built: same edges, same cfg_recent rule).
    reg [31:0] first0_q, first1_q;
    reg cfg_recent;
    always @(posedge ck) begin
        first0_q <= tv[31:0]; first1_q <= f1;
        cfg_recent <= cfg_we;
    end
    // first word fields: [17:0] by seg copy 0, [31:18] (dt) by seg copy 1
    wire [31:0] first = {seg_c[1] ? first1_q[31:18] : first0_q[31:18], seg_c[0] ? first1_q[17:0] : first0_q[17:0]};
    reg [31:0] cur;
    reg [13:0] cnt;
    reg [4:0]  rep, bcur;
    // running and a KEPT copy share one D net (run_d); the pointer's upper half advances on the copy
    (* keep = "true", dont_touch = "true" *) reg run_c;
    wire run_d = ht_a[3] ? 1'b0 : st_a[0] ? 1'b1 : (running && cnt == 14'd1 && rep == 5'd0 && cur[17]) ? 1'b0 : running;
    (* keep = "true", dont_touch = "true" *) always @(posedge ck or negedge rst_n)
        if (!rst_n) begin running <= 1'b0; run_c <= 1'b0; run_g <= 1'b0; end
        else begin running <= run_d; run_c <= run_d; run_g <= run_d; end
    wire adv   = running && cnt == 14'd1 && rep == 5'd0 && !cur[17];
    wire adv_h = run_c && cnt == 14'd1 && rep == 5'd0 && !cur[17];
    // ---- pointer: one-hot + lap bit, ONE D net for master and copy (ptr <= {0,sb}+1 / ptr+1 / hold) ----
    wire [NE-1:0] sel1_h = {sel1_c1[NE-1:H], sel1_c0[H-1:0]};
    wire [NE-1:0] st_s1  = {sel1_h[NE-2:0], sel1_h[NE-1]};       // one-hot (seg1 + 1) mod NE
    wire [NE-1:0] rot    = {pc0[NE-2:0], pc0[NE-1]};
    reg  [NE-1:0] pd;
    reg           phd;
    always @* begin
        for (k = 0; k < NE; k = k + 1) begin
            if ((k < H) ? ht_a[0] : ht_a[1]) pd[k] = pc0[k];
            else if ((k < H) ? st_a[2] : st_a[3]) pd[k] = ((k < H) ? seg_c[2] : seg_c[3]) ? st_s1[k] : (k == 1);
            else if ((k < H) ? adv : adv_h) pd[k] = rot[k];
            else pd[k] = pc0[k];
        end
        if (ht_a[1]) phd = ph;
        else if (st_a[3]) phd = seg_c[3] & sel1_c1[NE-1];
        else if (adv_h) phd = ph ^ pc0[NE-1];
        else phd = ph;
    end
    (* keep = "true", dont_touch = "true" *) always @(posedge ck or negedge rst_n)
        if (!rst_n) begin pc0 <= {{(NE-1){1'b0}}, 1'b1}; pc1 <= {{(NE-1){1'b0}}, 1'b1}; ph <= 1'b0; end
        else begin pc0 <= pd; pc1 <= pd; ph <= phd; end
    // ---- run state (as built; start copy 0) ----
    always @(posedge ck or negedge rst_n) begin
        if (!rst_n) begin
            ev_v <= 1'b0; ev_port <= 3'd0; ev_kind <= 4'd0; ev_beat <= 5'd0;
            cur <= 32'd0; fault <= 1'b0; rep <= 5'd0; bcur <= 5'd0;
        end else begin
            ev_v <= 1'b0;
            if (cfg_we && running) fault <= 1'b1;
            if (FEGON && (reject || poison)) fault <= 1'b1;               // first-epoch guard: fail-stop
            if (ht_a[3]) ;                                                       // running: run_d
            else if (st_a[0]) begin
                if (running || cfg_we || cfg_recent) fault <= 1'b1;
                cur <= first; rep <= first[4:0]; bcur <= first[9:5];
                if (first[31:18] == 14'd0 || {1'b0, first[9:5]} + {1'b0, first[4:0]} > 6'd31) fault <= 1'b1;
            end else if (running) begin
                if (cnt == 14'd1) begin
                    ev_v <= 1'b1; ev_port <= cur[16:14]; ev_kind <= cur[13:10]; ev_beat <= bcur;
                    if (rep != 5'd0) begin rep <= rep - 5'd1; bcur <= bcur + 5'd1; end   // burst: next cycle
                    else if (cur[17]) ;                                            // running: run_d
                    else begin
                        if (ph && pc0[0]) fault <= 1'b1;                               // ptr == NE
                        if (nxt[31:18] == 14'd0 || {1'b0, nxt[9:5]} + {1'b0, nxt[4:0]} > 6'd31) fault <= 1'b1;
                        cur <= nxt; rep <= nxt[4:0]; bcur <= nxt[9:5];
                    end
                end
            end
        end
    end
    // ---- interval counter (as built; start copy 1) ----
    always @(posedge ck or negedge rst_n) begin
        if (!rst_n) cnt <= 14'd0;
        else if (ht_a[2]) cnt <= cnt;
        else if (st_a[1]) cnt <= first[31:18];
        else if (running) begin
            if (cnt == 14'd1) begin
                if (rep == 5'd0 && !cur[17]) cnt <= nxt[31:18];
            end else cnt <= cnt - 1'b1;
        end
    end
`ifdef OT_FO_CHECK
    reg fo_armed = 1'b0;
    always @(posedge ck) begin
        if (fo_armed && (sel1_c1 !== sel1_c0 || pc1 !== pc0 || run_c !== running || ok_c !== {4{ok_c[0]}} || run_g !== running))
            $display("FO_COPY_MISMATCH %m t=%0t sel1 %h/%h pc %h/%h", $time, sel1_c0, sel1_c1, pc0, pc1);
        fo_armed <= 1'b1;
    end
`endif
endmodule

module ot_qwen_d2d_static_end_sfm #(
    parameter integer NT = 4, NR = 4, FW = 548, CW = 16, PW = FW + 19 + CW, NE = 32,
    parameter [8*4-1:0] TXD = {8'd1, 8'd1, 8'd2, 8'd1},
    parameter integer MUT = 0,
    parameter integer OVL = 0,
    parameter integer NRC = 4,
    parameter integer NG2 = 10,     // STATUS capture groups
    parameter integer FGB = 24,     // payload bits per producer capture copy
    parameter integer MUTFO = 0,
    parameter integer SRAMV = 1,
    parameter integer FEG = 1
) (
    input  wire [4:0]       ck,
    input  wire [NRC-1:0]   rst_n,
    input  wire [1:0]       por_c,        // local POR copies: [0] TX, [1] RX calendar receipt
    input  wire [1:0]       fg_we,        // guard pin copies of cfg_tx_we / cfg_rx_we
    input  wire [11:0]      fg_addr,      // guard pin copies of cfg_addr: [5:0] TX, [11:6] RX
    input  wire             cfg_tx_we, cfg_rx_we,
    input  wire [11:0]      cfg_addr_c,   // [5:0] TX calendar, [11:6] RX calendar (pin copies)
    input  wire [127:0]     cfg_data_c,   // [63:0] TX calendar halves, [127:64] RX calendar halves (pin copies)
    input  wire [9:0]       cfg_base_c,   // [4:0] TX, [9:5] RX: pin copies of cfg_data[4:0] for the base decode
    input  wire [9:0]       eb_c,
    input  wire             epoch_begin,
    input  wire [7:0]       epoch,
    input  wire             cal_start,    // OVL user tag only (the calendars use start_c)
    input  wire             cal_start_rx,
    input  wire [7:0]       start_c,      // [3:0] TX calendar, [7:4] RX calendar (OVL: the RX start pin)
    input  wire [7:0]       seg_c,
    input  wire [1:0]       cal_user_tx,
    input  wire [1:0]       cal_user_rx,
    output wire [1:0]       tx_user,
    output reg  [1:0]       rx_user,
    output wire [NT-1:0]    tx_slot,
    output wire [3:0]       tx_kind,
    output wire [4:0]       tx_beat,
    input  wire [NT-1:0]    tx_valid,
    input  wire [NT*FW-1:0] tx_payload,
    output reg  [NR-1:0]    rx_event,
    output reg  [NR-1:0]    rx_slot,
    output reg  [3:0]       rx_kind,
    output reg  [4:0]       rx_beat,
    output wire [FW-1:0]    rx_payload,
    output wire [NG2-1:0]   st_ev_c,      // copies of rx_event[2] (same D nets as the link's rx_v and r2p)
    output wire [NG2-1:0]   st_rs_c,      // copies of rx_slot[2]
    input  wire             p_tx_up,
    output wire             p_tx_v,
    output wire [PW-1:0]    p_tx_flit,
    input  wire             p_rx_v,
    input  wire [PW-1:0]    p_rx_flit,
    output wire             epoch_abort,
    output wire [7:0]       fault_cause,
    output reg              end_fault,
    output wire             cal_running
);
    generate if (NRC != 4) begin : g_nrc_unsupported
        OT_QWEN_D2D_END_SF_NEEDS_NRC4 u_nrc ();
    end endgenerate
    // halt = epoch_abort | end_fault as 9 copies: [3:0] TX calendar, [7:4] RX calendar, [8] this end (capture / write gate)
    wire [8:0] ab_x;
    (* keep = "true", dont_touch = "true" *) reg [8:0] efc;   // end_fault copies (same D net, below)
    wire [8:0] halt_c = ab_x | efc;
    wire halt = halt_c[8];
    wire rst_tc = rst_n[0], rst_cl = rst_n[1], rst_lk = rst_n[2], rst_rc = rst_n[3];
    wire tv, rv; wire [2:0] tp, rp; wire [3:0] tk, rk; wire [4:0] tb, rb; wire tf, rf, trun, rrun;
    ot_qwen_d2d_cal_sfg #(.NE(NE), .MUTFO(MUTFO), .FEG(FEG)) u_txcal (.por_n(por_c[0]), .fg_we(fg_we[0]), .fg_addr(fg_addr[5:0]), .ck(ck[0]), .rst_n(rst_tc), .cfg_we(cfg_tx_we),
        .cfg_addr(cfg_addr_c[5:0]), .cfg_data_c(cfg_data_c[63:0]), .cfg_base_c(cfg_base_c[4:0]), .start_c(start_c[3:0]),
        .seg_c(seg_c[3:0]), .halt_c(halt_c[3:0]),
        .ev_v(tv), .ev_port(tp), .ev_kind(tk), .ev_beat(tb), .running(trun), .fault(tf));
    ot_qwen_d2d_cal_sfg #(.NE(NE), .FEG(FEG)) u_rxcal (.por_n(por_c[1]), .fg_we(fg_we[1]), .fg_addr(fg_addr[11:6]), .ck(ck[0]), .rst_n(rst_rc), .cfg_we(cfg_rx_we),
        .cfg_addr(cfg_addr_c[11:6]), .cfg_data_c(cfg_data_c[127:64]), .cfg_base_c(cfg_base_c[9:5]), .start_c(start_c[7:4]),
        .seg_c(seg_c[7:4]), .halt_c(halt_c[7:4]),
        .ev_v(rv), .ev_port(rp), .ev_kind(rk), .ev_beat(rb), .running(rrun), .fault(rf));
    assign cal_running = trun | rrun;
    reg [1:0] utx, urx, r1u;
    generate if (OVL != 0) begin : g_ovl_user
        always @(posedge ck[0] or negedge rst_cl)
            if (!rst_cl) begin utx <= 2'd0; urx <= 2'd0; end
            else begin if (cal_start) utx <= cal_user_tx; if (cal_start_rx) urx <= cal_user_rx; end
        assign tx_user = utx;
    end else begin : g_one_user
        always @* begin utx = 2'd0; urx = 2'd0; end
        assign tx_user = 2'd0;
    end endgenerate
    genvar p, g;
    for (p = 0; p < NT; p = p + 1) begin : g_slot
        assign tx_slot[p] = tv && tp == p;
    end
    assign tx_kind = tk;
    assign tx_beat = tb;
    // per-port fixed capture delay (as built) + NFC copies of its last stage, D = the master's last-stage D net
    localparam integer NFC = (FW + FGB - 1) / FGB;
    reg [NT-1:0] fire;
    wire [NT*NFC-1:0] fire_c;
    for (p = 0; p < NT; p = p + 1) begin : g_dly
        localparam integer D = TXD[8*p +: 8];
        reg [D-1:0] sr;
        wire last_d = (D > 1) ? sr[(D > 1) ? D-2 : 0] : (tx_slot[p] & ~halt);
        wire early_d = (D > 2) ? sr[(D > 2) ? D-3 : 0] : last_d;
        (* keep = "true", dont_touch = "true" *) reg [NFC-1:0] fc;
        always @(posedge ck[0] or negedge rst_cl)
            if (!rst_cl) sr <= {D{1'b0}};
            else sr <= {sr, tx_slot[p] & ~halt};
        for (g = 0; g < NFC; g = g + 1) begin : g_fc
            (* keep = "true", dont_touch = "true" *) always @(posedge ck[0] or negedge rst_cl)
                if (!rst_cl) fc[g] <= 1'b0;
                else fc[g] <= (MUTFO == 3 && p == 0 && g == 5) ? early_d : last_d;
        end
        always @* fire[p] = sr[D-1];
        assign fire_c[NFC*p +: NFC] = fc;
    end
    integer i, j, k;
    reg [FW-1:0] wsel;
    reg          wobs;
    wire         multi = |(fire & (fire - 1'b1));
    always @* begin
        wsel = {FW{1'b0}}; wobs = 1'b0;
        for (j = 0; j < NT; j = j + 1) begin
            for (k = 0; k < FW; k = k + 1)
                if (fire_c[NFC*j + k/FGB]) wsel[k] = wsel[k] | tx_payload[j*FW + k];
            if (fire[j]) wobs = wobs | tx_valid[j];
        end
    end
    wire wr_v = |fire;
    wire stray = |(tx_valid & ~fire);
    wire bad_port;
    if (NT < 4) begin : g_bad_port
        assign bad_port = tv && tp >= NT;
    end else begin : g_all_ports
        assign bad_port = 1'b0;
    end
    // write / read slot counters: master + 5 copies (4 store banks + link control) on ONE D net each
    reg [5:0] wcnt, rslot; reg rd_v;
    wire [5:0] wslot = (MUT == 1) ? wcnt + 6'd1 : wcnt;
    wire eb8 = (MUTFO == 4) ? 1'b0 : eb_c[8];
    wire [5:0] wcnt_d = eb8 ? 6'd0 : (wr_v ? wcnt + 6'd1 : wcnt);
    wire [5:0] rslot_d = eb8 ? rslot : wslot;
    (* keep = "true", dont_touch = "true" *) reg [29:0] wc_c;
    (* keep = "true", dont_touch = "true" *) reg [29:0] rs_c;
    (* keep = "true", dont_touch = "true" *) always @(posedge ck[0] or negedge rst_cl)
        if (!rst_cl) begin wcnt <= 6'd0; rslot <= 6'd0; wc_c <= 30'd0; rs_c <= 30'd0; end
        else begin wcnt <= wcnt_d; rslot <= rslot_d; wc_c <= {5{wcnt_d}}; rs_c <= {5{rslot_d}}; end
    wire [29:0] ws_c;
    for (g = 0; g < 5; g = g + 1) begin : g_ws
        assign ws_c[6*g +: 6] = (MUT == 1) ? wc_c[6*g +: 6] + 6'd1 : wc_c[6*g +: 6];
    end
    // RX expectation and its 2-edge alignment with the slot link's checked output (as built; eb copies 8 / 9)
    reg [5:0] ecnt;
    reg       r1v, r2v; reg [2:0] r1p, r2p; reg [3:0] r1k; reg [4:0] r1b;
    always @(posedge ck[0] or negedge rst_cl) begin
        if (!rst_cl) begin
            rd_v <= 0; ecnt <= 0; end_fault <= 0; r1v <= 0; r2v <= 0; rx_slot <= 0;
        end else if (eb8) begin
            rd_v <= 0; ecnt <= 0; end_fault <= 0; r1v <= 0; r2v <= 0; rx_slot <= 0;
        end else begin
            rd_v <= wr_v & ~halt;
            if (rv) ecnt <= ecnt + 6'd1;
            if (stray | multi | tf | rf | bad_port) end_fault <= 1'b1;
            r1v <= rv; r2v <= r1v;
            for (i = 0; i < NR; i = i + 1) rx_slot[i] <= r1v && r1p == i;
        end
    end
    wire ef_d = eb8 ? 1'b0 : (end_fault | stray | multi | tf | rf | bad_port);
    (* keep = "true", dont_touch = "true" *) always @(posedge ck[0] or negedge rst_cl)
        if (!rst_cl) efc <= 9'd0; else efc <= {9{ef_d}};
    wire [2:0] r2p_n = (MUT == 2 && r1p < 2) ? r1p ^ 3'd1 : r1p;
    always @(posedge ck[0] or negedge rst_cl) begin
        if (!rst_cl) begin
            r1p <= 0; r2p <= 0; r1k <= 0; r1b <= 0; rx_kind <= 0; rx_beat <= 0; r1u <= 0; rx_user <= 0;
        end else if (!eb_c[9]) begin
            r1p <= rp; r1k <= rk; r1b <= rb; r1u <= urx; rx_user <= r1u;
            r2p <= r2p_n;
            rx_kind <= r1k; rx_beat <= r1b;
        end
    end
    // STATUS (port 2) capture copies: rx_event[2] = rx_v && r2p == 2, rx_slot[2]; same D nets, same resets
    wire lrx_v, lrx_v_nx;
    wire ev2_d = !eb_c[9] && lrx_v_nx && r2p_n == 3'd2;
    wire rs2_d = !eb8 && r1v && r1p == 3'd2;
    (* keep = "true", dont_touch = "true" *) reg [NG2-1:0] ev2_c;
    (* keep = "true", dont_touch = "true" *) reg [NG2-1:0] rs2_c;
    (* keep = "true", dont_touch = "true" *) always @(posedge ck[0] or negedge rst_lk)
        if (!rst_lk) ev2_c <= {NG2{1'b0}}; else ev2_c <= {NG2{ev2_d}};
    (* keep = "true", dont_touch = "true" *) always @(posedge ck[0] or negedge rst_cl)
        if (!rst_cl) rs2_c <= {NG2{1'b0}}; else rs2_c <= {NG2{rs2_d}};
    assign st_ev_c = ev2_c;
    assign st_rs_c = rs2_c;
    always @* for (k = 0; k < NR; k = k + 1) rx_event[k] = lrx_v && r2p == k;
    ot_qwen_static_slot_link_sfm #(.FW(FW), .CW(CW), .PW(PW), .MUTFO(MUTFO), .SRAMV(SRAMV)) u_link (
        .ck(ck), .rst_n(rst_lk), .eb_c(eb_c[7:0]), .epoch(epoch),
        .wr_v(wr_v & ~halt), .wr_observed_v(wobs), .wr_slot_c(ws_c), .wr_flit(wsel),
        .rd_v(rd_v), .rd_slot_c(rs_c),
        .rx_expect_v(rv), .rx_expect_slot(ecnt),
        .p_tx_up(p_tx_up), .p_tx_v(p_tx_v), .p_tx_flit(p_tx_flit), .p_rx_v(p_rx_v), .p_rx_flit(p_rx_flit),
        .rx_v(lrx_v), .rx_v_nx(lrx_v_nx), .rx_flit(rx_payload), .epoch_abort(epoch_abort), .ab_c(ab_x), .fault_cause(fault_cause));
`ifdef OT_FO_CHECK
    reg fo_armed = 1'b0;
    always @(posedge ck[0]) begin
        if (fo_armed && (wc_c !== {5{wcnt}} || rs_c !== {5{rslot}} || ev2_c !== {NG2{rx_event[2]}} ||
                         rs2_c !== {NG2{rx_slot[2]}} || efc !== {9{end_fault}} || ab_x !== {9{epoch_abort}}))
            $display("FO_COPY_MISMATCH %m t=%0t", $time);
        for (j = 0; j < NT; j = j + 1)
            if (fo_armed && fire_c[NFC*j +: NFC] !== {NFC{fire[j]}}) $display("FO_COPY_MISMATCH %m fire%0d t=%0t", j, $time);
        fo_armed <= 1'b1;
    end
`endif
endmodule

module ot_qwen_d2d_recovery_sfm #(
    parameter integer MASTER = 1, DRAIN = 32, RSTC = 16, BUMP = 3, NEB = 12
) (
    input  wire       ck,
    input  wire       por_n,
    input  wire       rst_n,
    input  wire       abort,
    input  wire [7:0] fault_cause,
    input  wire       end_fault,
    input  wire       p_tx_up,
    input  wire       p_tx_v, p_rx_v,
    input  wire       reset_req,
    input  wire       recovery_clear,
    input  wire       boot_begin,
    input  wire       fwd_epoch_i,
    output wire       fwd_epoch_o,
    output wire       fwd_link_rst_n,
    output wire       phy_rst_n,
    output wire       epoch_begin,      // = KEPT eb_m (never merged into its copies ebc)
    output reg  [7:0] epoch,
    output reg        link_up,
    output wire       links_drained,
    output wire       link_reset_seen,
    output wire       retrained,
    output reg  [7:0] transport_fault,
    output wire       recovering,
    output wire [31:0] recovery_cycles,
    output wire [NEB-1:0] epoch_begin_c
);
    localparam [2:0] S_RUN = 0, S_DRAIN = 1, S_DRAINED = 2, S_RST = 3, S_TRAIN = 4, S_READY = 5;
    // n counts the drain / reset intervals only: 0 .. max(DRAIN, RSTC) - 1 (cleared on every entry), so NW bits
    localparam integer NW = $clog2((DRAIN > RSTC) ? DRAIN : RSTC);
    reg [2:0] st; reg [NW-1:0] n; reg seen, lrst, fep, bq;
    reg [BUMP-1:0] eq;
    reg [BUMP-1:0] fq;
    reg counting;
    (* keep = "true", dont_touch = "true" *) reg eb_m;
    assign epoch_begin = eb_m;
    assign fwd_epoch_o = fep;
    assign fwd_link_rst_n = ~lrst;
    assign phy_rst_n = rst_n & ~lrst;
    assign links_drained = (st == S_DRAINED) || (st == S_RST) || (st == S_TRAIN) || (st == S_READY);
    assign link_reset_seen = seen;
    assign retrained = (st == S_READY);
    assign recovering = (st != S_RUN);
    wire begin_now = MASTER ? eq[BUMP-1] : fq[BUMP-1];
    always @(posedge ck or negedge por_n)
        if (!por_n) begin epoch <= 8'd0; end
        else if (epoch_begin) epoch <= epoch + 8'd1;
    (* keep = "true", dont_touch = "true" *) reg [5:0] stc;      // 2 copies of st (same D net st_d)
    (* keep = "true", dont_touch = "true" *) reg [1:0] cntc;     // 2 copies of counting
    (* keep = "true", dont_touch = "true" *) reg [NEB+2:0] ebc;  // NEB external + 3 internal copies of epoch_begin
    // ---- next state of st / counting (the as-built priority: begin_now first, the state case last) ----
    reg [2:0] st_d; reg cnt_d;
    always @* begin
        st_d = st; cnt_d = counting;
        if (begin_now) begin st_d = S_RUN; cnt_d = 1'b0; end
        case (st)
        S_RUN:     if (abort && !ebc[NEB+2]) begin st_d = MASTER ? S_DRAIN : S_READY; cnt_d = 1'b1; end
        S_DRAIN:   if (!(p_tx_v || p_rx_v) && n == DRAIN - 1) st_d = S_DRAINED;
        S_DRAINED: if (reset_req) st_d = S_RST;
        S_RST:     if (n == RSTC - 1) st_d = S_TRAIN;
        S_TRAIN:   if (seen && p_tx_up) st_d = S_READY;
        S_READY:   ;
        default:   st_d = S_RUN;
        endcase
    end
    (* keep = "true", dont_touch = "true" *) always @(posedge ck or negedge rst_n)
        if (!rst_n) begin st <= S_RUN; counting <= 1'b0; stc <= {2{S_RUN}}; cntc <= 2'd0; ebc <= {(NEB+3){1'b0}}; end
        else begin st <= st_d; counting <= cnt_d; stc <= {2{st_d}}; cntc <= {2{cnt_d}}; ebc <= {(NEB+3){begin_now}}; end
    assign epoch_begin_c = ebc[NEB-1:0];
    // ---- recovery_cycles: as built rc <= (S_RUN && abort && !epoch_begin) ? 0 : counting ? rc + 1 : rc; two halves ----
    reg [15:0] rc_lo, rc_hi;
    wire clr_lo = stc[2:0] == S_RUN && abort && !ebc[NEB];
    wire clr_hi = stc[5:3] == S_RUN && abort && !ebc[NEB+1];
    always @(posedge ck or negedge rst_n)
        if (!rst_n) rc_lo <= 16'd0;
        else if (clr_lo) rc_lo <= 16'd0;
        else if (cntc[0]) rc_lo <= rc_lo + 16'd1;
    always @(posedge ck or negedge rst_n)
        if (!rst_n) rc_hi <= 16'd0;
        else if (clr_hi) rc_hi <= 16'd0;
        else if (cntc[1] && rc_lo == 16'hffff) rc_hi <= rc_hi + 16'd1;
    assign recovery_cycles = {rc_hi, rc_lo};
    // ---- everything else as built ----
    always @(posedge ck or negedge rst_n) begin
        if (!rst_n) begin
            n <= 0; seen <= 0; lrst <= 0; fep <= 0; eq <= 0; fq <= 0; eb_m <= 0; bq <= 0; link_up <= 0;
            transport_fault <= 0;
        end else begin
            fep <= 1'b0; eb_m <= begin_now; bq <= boot_begin;
            link_up <= p_tx_up && (st == S_RUN) && !abort;
            eq <= {eq, fep}; fq <= {fq, fwd_epoch_i};
            if (begin_now) begin seen <= 0; transport_fault <= 0; end
            case (st)
            S_RUN: begin
                if (MASTER && boot_begin && !bq) fep <= 1'b1;
                if (abort && !ebc[NEB+2]) begin
                    n <= 0; transport_fault <= fault_cause | {end_fault, 7'd0};
                end
            end
            S_DRAIN: if (p_tx_v || p_rx_v) n <= 0; else if (n == DRAIN - 1) ; else n <= n + 1;
            S_DRAINED: if (reset_req) begin n <= 0; lrst <= 1; end
            S_RST: begin
                if (!p_tx_up) seen <= 1;
                if (n == RSTC - 1) lrst <= 0; else n <= n + 1;
            end
            S_TRAIN: ;
            S_READY: if (MASTER && recovery_clear) fep <= 1'b1;
            default: ;
            endcase
        end
    end
`ifdef OT_FO_CHECK
    reg fo_armed = 1'b0;
    always @(posedge ck) begin
        if (fo_armed && (stc !== {2{st}} || cntc !== {2{counting}} || ebc !== {(NEB+3){epoch_begin}}))
            $display("FO_COPY_MISMATCH %m t=%0t", $time);
        fo_armed <= 1'b1;
    end
`endif
endmodule

module qkd_d2d_static_core_sfm #(parameter integer MUT = 0, parameter integer NL = 2, parameter [31:0] TXDP = {8'd1, 8'd1, 8'd2, 8'd1},
    // S-QTIES QC-12 (10-18): KV-die TX lane count.  4 = closed qkd_d2d_static r7q (port 3 built, tied idle); 3 = the dead
    // port-3 TX lane removed (no KV->compute port-3 traffic in the compiled program; the end faults a port-3 TX event)
    parameter integer NTX = 4,
    parameter integer OVL = 0, parameter integer SAFE_RC = 1, parameter integer MUTFO = 0,
    parameter integer SRAMV = 1, parameter integer FEG = 1, parameter integer OBS1_COMPAT = 0) (   // MU-D2D-OVL 10-19: 1 = overlapping request / response segments
    input  wire         ck,                              // core D2D clock (PLL core trunk, 1.2 GHz; one CTS root incl. the slot-store SRAMs)
    input  wire         por_n, rst_n,
    input  wire         cfg_tx_we, cfg_rx_we, input wire [5:0] cfg_addr, input wire [31:0] cfg_data,
    input  wire         cal_start,                       // compiled run start (KV sequencer)
    input  wire         cal_seg,                         // 0 layer run, 1 token run (terminal RESULT / embedding row)
    input  wire         cal_start_rx, cal_seg_rx,         // OVL = 1: RX calendar start / segment (OVL = 0: unused)
    input  wire [1:0]   cal_user_tx, cal_user_rx,         // OVL = 1: user of the segment started on this edge
    output wire [1:0]   tx_user, rx_user,                 // OVL = 1: user of every TX slot / RX event (0 when OVL = 0)
    // HOST (qkd_host_root_pt) control of the exceptional mode
    input  wire         host_link_reset_req, host_recovery_clear, host_boot_begin,
    output wire         fwd_epoch, fwd_link_rst_n,       // bumps to the compute die
    // attention record (KV_SIDE 1)
    output wire         att_tx_slot, output wire [3:0] att_tx_kind, output wire [4:0] att_tx_beat,
    input  wire         att_tx_v, input wire [547:0] att_tx_payload,
    output wire         att_rx_v, output wire att_rx_slot, output wire [3:0] att_rx_kind, output wire [4:0] att_rx_beat,
    output wire [547:0] rx_payload,
    // embedding row (TX port 2; producer: KV die embedding provider, row staged before its compiled token run)
    output wire         emb_tx_slot,
    input  wire         emb_tx_v, input wire [547:0] emb_tx_payload,
    // HOST record port (to qkd_host_root_pt record_* ports)
    input  wire         record_tx_observed_v, input wire [547:0] record_tx,
    output wire [1:0]   record_send_kind, output wire record_witness_slot, record_rx_v, output wire [547:0] record_rx,
    // KVN to qkd_kv_static_writer_native
    input  wire [58:0]  kvn_compiled_identity, input wire [1:0] kvn_compiled_generation,
    output wire         kvn_word_valid, output wire [10:0] kvn_word_tag, output wire [511:0] kvn_word_data,
    output wire [58:0]  kvn_word_identity, output wire [1:0] kvn_word_generation,
    output wire         kvn_word_slot, output wire [1:0] kvn_word_index,
    // HOST root inputs produced here (see qkd_host_link_services)
    input  wire [15:0]  status_epoch16,
    input  wire         serdes_up, kv_drained_local, kv_flush_local, host_drained_local, kv_active_local,
    output wire [NL-1:0] link_up, output wire [7:0] transport_fault,
    output wire         native_links_drained, native_link_reset_seen, native_retrained,
    output wire [3:0]   abort_drained,
    output wire         native_kv_drained, native_vm_drained, native_collective_drained, native_host_drained,
    output wire         native_collective_busy, native_kv_flush, native_admit_ready, crom_fault, execution_active,
    output wire         engine_result_v, engine_result_done, engine_result_fault, output wire [3:0] engine_result_cause,
    output wire [58:0]  engine_result_tag, output wire [1:0] engine_result_gen, output wire [17:0] engine_result_token,
    output wire [31:0]  engine_result_value, engine_result_cycles,
    // PHY FDI (ot_qkvd_ucie_x64_phy, 583)
    input  wire         fdi_tx_up, output wire fdi_tx_v, output wire [582:0] fdi_tx_flit,
    input  wire         fdi_rx_v, input wire [582:0] fdi_rx_flit,
    output wire         phy_rst_n,
    output wire         epoch_abort, output wire [31:0] recovery_cycles, output wire fault,
    // identical pin-flop copies (wrapper): cal_start / cal_seg [3:0] TX calendar, [7:4] RX calendar; cfg_addr [5:0] TX,
    // [11:6] RX; cfg_data [63:0] TX table halves, [127:64] RX table halves
    input  wire [7:0]   sf_start, sf_seg, input wire [11:0] sf_cfg_addr, input wire [127:0] sf_cfg_data,
    input  wire [9:0]   sf_cfg_base,
    input  wire [1:0]   fg_we, input wire [11:0] fg_addr   // first-epoch guard pin copies (wrapper)
);
    generate if (SAFE_RC != 1) begin : g_sfo_needs_rc
        QKD_D2D_SAFE_FO_NEEDS_SAFE_RC1 u_sfo_rc ();
    end endgenerate
    localparam integer NEB = 12;   // epoch_begin copies: [7:0] slot link, [9:8] end, [10] STATUS / KVN, [11] spare
    localparam integer RCP = 12;   // reset copies per region (ot_rst_pipe COPIES; OT_RST_COPIES_MAX spreads the loads)
    localparam integer NG2 = 10;   // STATUS capture groups
    wire [NEB-1:0] ebc;
    wire [NG2-1:0] st_ev_c, st_rs_c;
    // Global reset reaches only this short synchronizer; regional registered
    // reset nets remove port-to-consumer recovery/removal chains. Cold release +4
    // edges is exceptional initialization, outside the normal compiled timeline.
    localparam integer NREG = SAFE_RC ? 7 : 4;
    wire [NREG-1:0] local_rst_n;
    ot_rst_pipe #(.REGIONS(NREG), .STAGES(2), .COPIES(RCP)) u_reset_regions
        (.clk(ck), .rst_n_in(rst_n), .rst_n(local_rst_n));
    // Cold POR is captured locally just like the ordinary reset pin. Four
    // exceptional release edges; no change to the compiled normal calendar.
    wire [0:0] local_por_n;
    ot_rst_pipe #(.REGIONS(1), .STAGES(2), .COPIES(RCP)) u_por_region
        (.clk(ck), .rst_n_in(por_n), .rst_n(local_por_n));
    // Equal-depth KEPT reset copies: TX calendar/control/link/RX calendar share the original release edge.
    wire [(SAFE_RC ? 4 : 1)-1:0] end_rst_n;
    generate if (SAFE_RC) begin : g_safe_rc
        assign end_rst_n = {local_rst_n[6],local_rst_n[5],local_rst_n[4],local_rst_n[1]};
    end else begin : g_safe_rc0
        assign end_rst_n = local_rst_n[1];
    end endgenerate
    localparam integer FW = 548;
    wire [NTX-1:0] txs; wire [3:0] rxe, rxs; wire [3:0] tk, rk; wire [4:0] tb, rb; wire [FW-1:0] rxp;
    wire [NTX-1:0] tv; wire [NTX*FW-1:0] tp;
    wire eb, ab, endf, lu, dr, seen, rt, rec; wire [7:0] ep, fc, tf;
    wire s_vm, s_co, s_cb, s_cf, s_ea, s_ar, s_fr, s_f, kvn_f;
    ot_qwen_d2d_recovery_sfm #(.MASTER(1), .NEB(NEB)) u_rec (.ck(ck), .por_n(local_por_n[0]), .rst_n(local_rst_n[0]), .abort(ab | endf),
        .fault_cause(fc), .end_fault(endf), .p_tx_up(fdi_tx_up), .p_tx_v(fdi_tx_v), .p_rx_v(fdi_rx_v),
        .reset_req(host_link_reset_req), .recovery_clear(host_recovery_clear), .boot_begin(host_boot_begin),
        .fwd_epoch_i(1'b0), .fwd_epoch_o(fwd_epoch), .fwd_link_rst_n(fwd_link_rst_n), .phy_rst_n(phy_rst_n),
        .epoch_begin(eb), .epoch(ep), .link_up(lu), .links_drained(dr), .link_reset_seen(seen), .retrained(rt),
        .transport_fault(tf), .recovering(rec), .recovery_cycles(recovery_cycles), .epoch_begin_c(ebc));
    ot_qwen_d2d_static_end_sfm #(.NT(NTX), .NR(4), .TXD(TXDP), .MUT(MUT), .OVL(OVL), .NRC(4), .NG2(NG2), .MUTFO(MUTFO), .SRAMV(SRAMV), .FEG(FEG)) u_end (.por_c({2{local_por_n[0]}}), .fg_we(fg_we), .fg_addr(fg_addr),
        .ck({5{ck}}), .rst_n(end_rst_n), .cfg_tx_we(cfg_tx_we), .cfg_rx_we(cfg_rx_we), .cfg_addr_c(sf_cfg_addr), .cfg_data_c(sf_cfg_data), .cfg_base_c(sf_cfg_base), .eb_c(ebc[9:0]),
        .epoch_begin(eb), .epoch(ep), .cal_start(cal_start), .start_c(sf_start), .seg_c(sf_seg),
        .cal_start_rx(cal_start_rx), .cal_user_tx(cal_user_tx), .cal_user_rx(cal_user_rx),
        .tx_user(tx_user), .rx_user(rx_user),
        .tx_slot(txs), .tx_kind(tk), .tx_beat(tb), .tx_valid(tv), .tx_payload(tp),
        .rx_event(rxe), .rx_slot(rxs), .rx_kind(rk), .rx_beat(rb), .rx_payload(rxp), .st_ev_c(st_ev_c), .st_rs_c(st_rs_c),
        .p_tx_up(fdi_tx_up), .p_tx_v(fdi_tx_v), .p_tx_flit(fdi_tx_flit), .p_rx_v(fdi_rx_v), .p_rx_flit(fdi_rx_flit),
        .epoch_abort(ab), .fault_cause(fc), .end_fault(endf), .cal_running());
    assign epoch_abort = ab;
    assign rx_payload = rxp;
    assign att_tx_slot = txs[0]; assign att_tx_kind = tk; assign att_tx_beat = tb;
    assign tv[0] = att_tx_v; assign tp[0 +: FW] = att_tx_payload;
    assign att_rx_v = rxe[0]; assign att_rx_slot = rxs[0]; assign att_rx_kind = rk; assign att_rx_beat = rb;
    assign tv[1] = record_tx_observed_v; assign tp[FW +: FW] = record_tx;
    // port 2 embedding row (codec latency 1: the provider's registered word one edge after emb_tx_slot)
    assign emb_tx_slot = txs[2];
    assign tv[2] = emb_tx_v; assign tp[2*FW +: FW] = emb_tx_payload;
    // port 3 carries no KV-die TX traffic in the compiled program: NTX = 4 keeps the built lane tied idle (the end faults
    // any stray valid); NTX = 3 does not build it (QC-12) and the end faults a calendar event naming port 3
    if (NTX == 4) begin : g_tx3_idle
        assign tv[3] = 1'b0; assign tp[4*FW-1:3*FW] = {FW{1'b0}};
    end
    ot_qwen_d2d_status_rx_sf #(.NG(NG2), .OBS1_COMPAT(OBS1_COMPAT)) u_st (.ck(ck), .rst_n(local_rst_n[2]), .epoch16(status_epoch16), .rx_event(rxe[2]), .rx_slot(rxs[2]),
        .ev_c(st_ev_c), .rs_c(st_rs_c),
        .rx_payload(rxp), .vm_drained(s_vm), .collective_drained(s_co), .collective_busy(s_cb), .crom_fault(s_cf),
        .execution_active(s_ea), .admit_ready(s_ar), .status_fresh(s_fr), .result_v(engine_result_v),
        .result_done(engine_result_done), .result_fault(engine_result_fault), .result_cause(engine_result_cause),
        .result_tag(engine_result_tag), .result_gen(engine_result_gen), .result_token(engine_result_token),
        .result_value(engine_result_value), .result_cycles(engine_result_cycles), .epoch_begin(ebc[10]), .fault(s_f));
    ot_qwen_d2d_kvn_rx u_kvn (.ck(ck), .rst_n(local_rst_n[3] & ~ebc[10]), .rx_event(rxe[3]), .rx_slot(rxs[3]), .rx_beat(rb),
        .rx_payload(rxp), .compiled_identity(kvn_compiled_identity), .compiled_generation(kvn_compiled_generation),
        .word_valid(kvn_word_valid), .word_tag(kvn_word_tag), .word_data(kvn_word_data),
        .word_identity(kvn_word_identity), .word_generation(kvn_word_generation), .word_slot(kvn_word_slot),
        .word_index(kvn_word_index), .fault(kvn_f));
    qkd_host_link_services #(.NL(NL)) u_hls (.ck(ck), .rst_n(local_rst_n[3]),
        .d2d_link_up(lu), .serdes_up(serdes_up), .d2d_transport_fault(tf), .d2d_links_drained(dr),
        .d2d_link_reset_seen(seen), .d2d_retrained(rt),
        .rec_tx_slot(txs[1]), .rec_tx_kind(tk), .rec_tx_beat(tb), .rec_rx_event(rxe[1]), .rec_rx_slot(rxs[1]), .rec_rx_kind(rk),
        .rx_payload(rxp), .c_vm_drained(s_vm), .c_collective_drained(s_co), .c_collective_busy(s_cb),
        .c_crom_fault(s_cf), .c_execution_active(s_ea), .c_admit_ready(s_ar), .c_status_fresh(s_fr),
        .kv_drained_local(kv_drained_local), .kv_flush_local(kv_flush_local), .host_drained_local(host_drained_local),
        .kv_active_local(kv_active_local),
        .link_up(link_up), .transport_fault(transport_fault), .native_links_drained(native_links_drained),
        .native_link_reset_seen(native_link_reset_seen), .native_retrained(native_retrained),
        .abort_drained(abort_drained), .native_kv_drained(native_kv_drained), .native_vm_drained(native_vm_drained),
        .native_collective_drained(native_collective_drained), .native_host_drained(native_host_drained),
        .native_collective_busy(native_collective_busy), .native_kv_flush(native_kv_flush),
        .native_admit_ready(native_admit_ready), .crom_fault(crom_fault), .execution_active(execution_active),
        .record_send_kind(record_send_kind), .record_witness_slot(record_witness_slot), .record_rx_v(record_rx_v),
        .record_rx(record_rx));
    assign fault = endf | s_f | kvn_f;
endmodule

module qkd_d2d_static_sfm #(parameter integer MUT = 0, parameter integer NL = 2, parameter integer NTX = 4, parameter integer SAFE_RC = 1, parameter integer MUTFO = 0, parameter integer SRAMV = 1, parameter integer FEG = 1, parameter integer PR = 1, parameter integer OBS1_COMPAT = 0, parameter [31:0] TXDP = 32'd0) (
    input  wire ck,
    input  wire por_n,
    input  wire rst_n,
    input  wire cfg_tx_we,
    input  wire cfg_rx_we,
    input  wire [5:0] cfg_addr,
    input  wire [31:0] cfg_data,
    input  wire cal_start,
    input  wire cal_seg,
    input  wire host_link_reset_req,
    input  wire host_recovery_clear,
    input  wire host_boot_begin,
    output wire fwd_epoch,
    output wire fwd_link_rst_n,
    output wire att_tx_slot,
    output wire [3:0] att_tx_kind,
    output wire [4:0] att_tx_beat,
    input  wire att_tx_v,
    input  wire [547:0] att_tx_payload,
    output wire att_rx_v,
    output wire att_rx_slot,
    output wire [3:0] att_rx_kind,
    output wire [4:0] att_rx_beat,
    output wire [547:0] rx_payload,
    output wire [16:0] rx_zero17,
    output wire emb_tx_slot,
    input  wire emb_tx_v,
    input  wire [547:0] emb_tx_payload,
    input  wire record_tx_observed_v,
    input  wire [547:0] record_tx,
    output wire [1:0] record_send_kind,
    output wire record_witness_slot,
    output wire record_rx_v,
    output wire [547:0] record_rx,
    input  wire [58:0] kvn_compiled_identity,
    input  wire [1:0] kvn_compiled_generation,
    output wire kvn_word_valid,
    output wire [10:0] kvn_word_tag,
    output wire [511:0] kvn_word_data,
    output wire [58:0] kvn_word_identity,
    output wire [1:0] kvn_word_generation,
    output wire kvn_word_slot,
    output wire [1:0] kvn_word_index,
    input  wire [15:0] status_epoch16,
    input  wire serdes_up,
    input  wire kv_drained_local,
    input  wire kv_flush_local,
    input  wire host_drained_local,
    input  wire kv_active_local,
    output wire [NL-1:0] link_up,
    output wire [7:0] transport_fault,
    output wire native_links_drained,
    output wire native_link_reset_seen,
    output wire native_retrained,
    output wire [3:0] abort_drained,
    output wire native_kv_drained,
    output wire native_vm_drained,
    output wire native_collective_drained,
    output wire native_host_drained,
    output wire native_collective_busy,
    output wire native_kv_flush,
    output wire native_admit_ready,
    output wire crom_fault,
    output wire execution_active,
    output wire engine_result_v,
    output wire engine_result_done,
    output wire engine_result_fault,
    output wire [3:0] engine_result_cause,
    output wire [58:0] engine_result_tag,
    output wire [1:0] engine_result_gen,
    output wire [17:0] engine_result_token,
    output wire [31:0] engine_result_value,
    output wire [31:0] engine_result_cycles,
    input  wire fdi_tx_up,
    output wire fdi_tx_v,
    output wire [582:0] fdi_tx_flit,
    input  wire fdi_rx_v,
    input  wire [582:0] fdi_rx_flit,
    output wire phy_rst_n,
    output wire epoch_abort,
    output wire [31:0] recovery_cycles,
    output wire fault
);
    // TXDP = the compiler's per-TX-port producer capture latency (port p = byte p, 1..255 edges), set by the die GEN
    // from d2d_cal_image.svh (D2D_TXDP_C / D2D_TXDP_K, tools/qwen_split/d2d_cal_seq_image.py) or txdp.svh
    // (tools/qwen_split/d2d_link_calendar.py).  No production default exists: PR = 1 with an uncompiled (zero) port
    // byte does not elaborate (QXF-LINK 2026-10-18, TOKEN-XDIE-QWEN F4; the r4..r9 masters hard-wired the
    // component-bench codec latencies).
    generate if (PR != 0 && (TXDP[7:0] == 8'd0 || TXDP[15:8] == 8'd0 || TXDP[23:16] == 8'd0 || TXDP[31:24] == 8'd0)) begin : g_txdp_uncompiled
        D2D_TXDP_NOT_COMPILED__set_TXDP_from_the_compiler u_txdp_uncompiled ();
    end endgenerate
    wire c_cfg_tx_we;
    reg q_cfg_tx_we;
    always @(posedge ck) q_cfg_tx_we <= cfg_tx_we;
    assign c_cfg_tx_we = PR ? q_cfg_tx_we : cfg_tx_we;
    wire c_cfg_rx_we;
    reg q_cfg_rx_we;
    always @(posedge ck) q_cfg_rx_we <= cfg_rx_we;
    assign c_cfg_rx_we = PR ? q_cfg_rx_we : cfg_rx_we;
    wire [5:0] c_cfg_addr;
    reg [5:0] q_cfg_addr;
    always @(posedge ck) q_cfg_addr <= cfg_addr;
    assign c_cfg_addr = PR ? q_cfg_addr : cfg_addr;
    wire [31:0] c_cfg_data;
    reg [31:0] q_cfg_data;
    always @(posedge ck) q_cfg_data <= cfg_data;
    assign c_cfg_data = PR ? q_cfg_data : cfg_data;
    // KV-D2D SAFE FAN-OUT (d2d_safe_fo_masters.py): identical KEPT pin-flop copies.  Each samples the same pin as the
    // original pin flop, so it equals that flop from the first edge; the calendars load one field group per copy.
    generate if (PR != 1) begin : g_sfo_needs_pr
        QKD_D2D_SAFE_FO_NEEDS_PR1 u_sfo_pr ();
    end endgenerate
    wire sf_rx_start_pin = cal_start, sf_rx_seg_pin = cal_seg;   // RX calendar start / segment pins (OVL: the RX pins)
    (* keep = "true", dont_touch = "true" *) reg [7:0] q_sf_start;
